// NewDictionary returns the object dictionary for a node, every value at
// its default.
func NewDictionary(node canopen.NodeID) (*od.Dictionary, error) {
	d := od.New(node)
	for _, o := range Objects() {
		if err := d.Add(o); err != nil {
			return nil, err
		}
	}
	return d, nil
}

// Local reads and writes the dictionary of this node with Go types.
// Local accesses bypass the access rights (see od.Dictionary.Get and
// Set); setters check the range of the data type.
type Local struct{ D *od.Dictionary }

