// SDO is the SDO client Remote uses; a go-canopen sdo.Client satisfies
// it.
type SDO interface {
	Upload(ctx context.Context, index uint16, sub uint8) ([]byte, error)
	Download(ctx context.Context, index uint16, sub uint8, data []byte) error
}

// Remote reads and writes the dictionary of a remote node with Go types,
// over SDO: getters for the readable and setters for the writable
// sub-objects.
type Remote struct{ SDO SDO }

// DeviceType uploads 1000:00 Device type (UNSIGNED32, ro).
func (r Remote) DeviceType(ctx context.Context) (uint32, error) {
	b, err := r.SDO.Upload(ctx, IndexDeviceType, 0)
	x, err := asUint(canopen.Unsigned32, b, err)
	return uint32(x), err
}

// ErrorRegister uploads 1001:00 Error register (UNSIGNED8, ro).
func (r Remote) ErrorRegister(ctx context.Context) (uint8, error) {
	b, err := r.SDO.Upload(ctx, IndexErrorRegister, 0)
	x, err := asUint(canopen.Unsigned8, b, err)
	return uint8(x), err
}

// ManufacturerDeviceName uploads 1008:00 Manufacturer device name (VISIBLE_STRING, const).
func (r Remote) ManufacturerDeviceName(ctx context.Context) (string, error) {
	b, err := r.SDO.Upload(ctx, IndexManufacturerDeviceName, 0)
	return asString(canopen.VisibleString, b, err)
}

